import FeatureSectionV3 from "./components/feature-section-v3"

export default function Page() {
  return <FeatureSectionV3 />
}

import type { ComponentType } from "react"

import { GeistMono } from "geist/font/mono"

import { Card, CardContent, CardTitle } from "@/components/ui/card"

import DropoffIllustration from "./dropoff-illustration"
import ExperimentIllustration from "./experiment-illustration"
import { FeatureCardMedia } from "./feature-card-media"
import FunnelIllustration from "./funnel-illustration"
import { features, type FeatureIllustrationId } from "../lib/features"

const illustrationComponents: Record<FeatureIllustrationId, ComponentType> = {
  "funnel-opportunities": FunnelIllustration,
  "dropoff-diagnosis": DropoffIllustration,
  "experiment-impact": ExperimentIllustration,
}

export default function FeatureShowcase() {
  return (
    <ul className="m-0 grid list-none grid-cols-1 gap-4 p-0 md:grid-cols-3">
      {features.map(({ id, step, title, description, illustration }) => {
        const Illustration = illustrationComponents[illustration]

        return (
          <li key={id} className="flex min-w-0 flex-col">
            <Card className="group/card flex h-full min-h-80 flex-col gap-0 py-0">
              <FeatureCardMedia>
                <Illustration />
              </FeatureCardMedia>
              <CardContent className="flex flex-col gap-0 px-3.5 pt-3 pb-2.25">
                <p
                  className={`${GeistMono.className} m-0 mb-1 shrink-0 text-2.75 leading-[1.2] font-medium tracking-[0.14em] text-foreground/85`}
                >
                  {step}
                </p>
                <CardTitle className="m-0 mb-1.25 min-h-[calc(0.95rem*1.35*2)] text-3.8 leading-[1.35] font-semibold tracking-normal text-foreground">
                  {title}
                </CardTitle>
                <p className="m-0 shrink-0 text-3.25 leading-normal text-muted-foreground">
                  {description}
                </p>
              </CardContent>
            </Card>
          </li>
        )
      })}
    </ul>
  )
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

import { FEATURE_CARD_MEDIA_HEIGHT } from "./feature-illustration"

type FeatureCardMediaProps = {
  children: ReactNode
  className?: string
}

export function FeatureCardMedia({ children, className }: FeatureCardMediaProps) {
  return (
    <div
      className={cn(
        "flex w-full shrink-0 items-center justify-center border-b border-border/60 bg-muted/20 p-4",
        FEATURE_CARD_MEDIA_HEIGHT,
        className
      )}
      aria-hidden
    >
      <div className="h-full max-h-full w-full max-w-full min-h-0 overflow-hidden">
        {children}
      </div>
    </div>
  )
}

"use client"

import { cn } from "@/lib/utils"

import { MockScreen } from "./mock-screen"
import { useInViewOnce } from "../lib/use-in-view-once"

const WEDGES: ReadonlyArray<{
  label: string
  users: string
  width: string
  gap?: boolean
}> = [
  { label: "Visit", users: "12.4k", width: "92%" },
  { label: "Signup", users: "4.1k", width: "74%" },
  { label: "Activate", users: "1.8k", width: "52%", gap: true },
  { label: "Paid", users: "640", width: "34%" },
]

export default function FunnelIllustration() {
  const { ref, active } = useInViewOnce()

  return (
    <div ref={ref} className="size-full min-h-0 p-1">
      <MockScreen
        label="Funnel stages with a drop-off gap on Activate"
        className={cn("fsv3-fn-mock", active && "fsv3-fn-mock--active")}
      >
        <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-1.5 px-3 py-3">
          {WEDGES.map((wedge, index) => (
            <div
              key={wedge.label}
              className={cn(
                "fsv3-fn-wedge relative flex w-full flex-col items-center",
                `fsv3-fn-wedge--${index + 1}`,
                wedge.gap &&
                  "origin-center motion-safe:transition-transform duration-200 ease-out group-hover/card:scale-[1.03]"
              )}
            >
              <div
                className={cn(
                  "flex h-7 items-center justify-between gap-2 rounded-sm border border-border/65 bg-muted/35 px-2",
                  wedge.gap && "border-foreground/40 bg-muted/65"
                )}
                style={{ width: wedge.width }}
              >
                <span className="font-mono text-[0.5625rem] text-foreground/80">
                  {wedge.label}
                </span>
                <span className="font-mono text-[0.5625rem] text-muted-foreground tabular-nums">
                  {wedge.users}
                </span>
              </div>
              {wedge.gap ? (
                <span className="fsv3-fn-gap-mark mt-0.5 font-mono text-[0.5rem] tracking-[0.12em] text-foreground/70 uppercase">
                  gap · −56%
                </span>
              ) : null}
            </div>
          ))}
        </div>
      </MockScreen>
    </div>
  )
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

type MockScreenProps = {
  children: ReactNode
  className?: string
  label: string
}

export function MockScreen({ children, className, label }: MockScreenProps) {
  return (
    <div
      className={cn(
        "fsv3-mock flex size-full min-h-0 flex-col overflow-hidden rounded-xl border border-border/70 bg-card text-foreground opacity-70 shadow-sm motion-safe:transition-opacity duration-200 ease-out group-hover/card:opacity-100",
        className
      )}
      role="img"
      aria-label={label}
    >
      {children}
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

export function useInViewOnce(threshold = 0.35) {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el || active) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setActive(true)
          observer.disconnect()
        }
      },
      { threshold }
    )

    observer.observe(el)
    return () => observer.disconnect()
  }, [active, threshold])

  return { ref, active }
}

@keyframes fsv3-mock-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fsv3-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fsv3-pop {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.fsv3-fn-wedge,
.fsv3-fn-gap-mark,
.fsv3-do-stop,
.fsv3-do-pin,
.fsv3-ex-side,
.fsv3-ex-vs,
.fsv3-ex-result {
  opacity: 0;
}

.fsv3-fn-mock--active .fsv3-fn-wedge--1 {
  animation: fsv3-mock-in 400ms cubic-bezier(0.22, 1, 0.36, 1) 60ms forwards;
}

.fsv3-fn-mock--active .fsv3-fn-wedge--2 {
  animation: fsv3-mock-in 400ms cubic-bezier(0.22, 1, 0.36, 1) 140ms forwards;
}

.fsv3-fn-mock--active .fsv3-fn-wedge--3 {
  animation: fsv3-mock-in 460ms cubic-bezier(0.22, 1, 0.36, 1) 220ms forwards;
}

.fsv3-fn-mock--active .fsv3-fn-wedge--4 {
  animation: fsv3-mock-in 400ms ease-out 300ms forwards;
}

.fsv3-fn-mock--active .fsv3-fn-gap-mark {
  animation: fsv3-fade-in 360ms ease-out 480ms forwards;
}

.fsv3-do-mock--active .fsv3-do-stop--1 {
  animation: fsv3-mock-in 320ms ease-out 60ms forwards;
}

.fsv3-do-mock--active .fsv3-do-stop--2 {
  animation: fsv3-mock-in 320ms ease-out 120ms forwards;
}

.fsv3-do-mock--active .fsv3-do-stop--3 {
  animation: fsv3-pop 420ms cubic-bezier(0.22, 1, 0.36, 1) 200ms forwards;
}

.fsv3-do-mock--active .fsv3-do-stop--4 {
  animation: fsv3-mock-in 320ms ease-out 280ms forwards;
}

.fsv3-do-mock--active .fsv3-do-pin {
  animation: fsv3-mock-in 420ms cubic-bezier(0.22, 1, 0.36, 1) 380ms forwards;
}

.fsv3-ex-mock--active .fsv3-ex-side--a {
  animation: fsv3-mock-in 360ms ease-out 80ms forwards;
}

.fsv3-ex-mock--active .fsv3-ex-vs {
  animation: fsv3-fade-in 280ms ease-out 160ms forwards;
}

.fsv3-ex-mock--active .fsv3-ex-side--b {
  animation: fsv3-pop 420ms cubic-bezier(0.22, 1, 0.36, 1) 220ms forwards;
}

.fsv3-ex-mock--active .fsv3-ex-result {
  animation: fsv3-mock-in 400ms cubic-bezier(0.22, 1, 0.36, 1) 380ms forwards;
}

@media (prefers-reduced-motion: reduce) {
  .fsv3-fn-wedge,
  .fsv3-fn-gap-mark,
  .fsv3-do-stop,
  .fsv3-do-pin,
  .fsv3-ex-side,
  .fsv3-ex-vs,
  .fsv3-ex-result {
    opacity: 1;
    transform: none;
    animation: none;
  }
}
